CREATE OR REPLACE FUNCTION public.protect_upload_validation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ BEGIN IF auth.role()='authenticated' THEN IF TG_OP='INSERT' AND NEW.validated_at IS NOT NULL THEN RAISE EXCEPTION 'Only the file checker can validate an upload.'; END IF; IF TG_OP='UPDATE' AND (NEW.validated_at IS DISTINCT FROM OLD.validated_at OR (to_jsonb(NEW)->'download_only') IS DISTINCT FROM (to_jsonb(OLD)->'download_only') OR (OLD.validated_at IS NOT NULL AND (NEW.storage_path IS DISTINCT FROM OLD.storage_path OR NEW.mime_type IS DISTINCT FROM OLD.mime_type OR NEW.size_bytes IS DISTINCT FROM OLD.size_bytes))) THEN RAISE EXCEPTION 'Validated file details cannot be changed. Upload a new version instead.'; END IF; END IF; RETURN NEW; END $$;